import csv
from collections import defaultdict
from datetime import datetime
import sys

def parse_time(time_str):
    """Parse time string in HH:MM format"""
    return datetime.strptime(time_str, "%H:%M")

def is_late(arrival_time, threshold="09:00"):
    """Check if arrival time is later than threshold"""
    return parse_time(arrival_time) > parse_time(threshold)

def analyze_attendance(csv_file):
    """Analyze attendance data and count late arrivals per employee"""
    late_counts = defaultdict(int)

    with open(csv_file, 'r') as file:
        reader = csv.DictReader(file)
        for row in reader:
            name = row['Name']
            clock_in = row['Clock-in']

            if is_late(clock_in):
                late_counts[name] += 1

    # Sort employees by late count (descending)
    sorted_employees = sorted(late_counts.items(), key=lambda x: x[1], reverse=True)

    return sorted_employees

def append_top_five_to_file(employees, filename):
    """Append top 5 employees with most late arrivals to file"""
    top_five = employees[:5]

    with open(filename, 'a') as file:
        file.write("\n")
        for name, count in top_five:
            file.write(f"{name}\n")

def main():
    if len(sys.argv) != 2:
        print("Usage: python attendance_analyzer.py <csv_file>")
        sys.exit(1)

    csv_file = sys.argv[1]

    try:
        late_employees = analyze_attendance(csv_file)

        if not late_employees:
            print("No late arrivals found.")
            return

        print("Top 5 employees with most late arrivals:")
        for i, (name, count) in enumerate(late_employees[:5], 1):
            print(f"{i}. {name}: {count} late arrivals")

        append_top_five_to_file(late_employees, "problematic_employees.txt")
        print("\nTop 5 employees appended to problematic_employees.txt")

    except FileNotFoundError:
        print(f"Error: File '{csv_file}' not found.")
        sys.exit(1)
    except Exception as e:
        print(f"Error: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()
